const endereco = (cep, logradouro, numero, complemento, bairro, cidade, uf) => ({ cep, logradouro, numero, complemento, bairro, cidade, uf });
const enderecoVazio = () => endereco('', '', '', '', '', '', '');

function empresaSeed(d) {
  return {
    nomeFantasia: '', inscricaoEstadual: '', site: '', porte: null, segmento: null, status: 'ativo', origem: null, observacoes: '',
    email: '', telefone: '',
    endereco: enderecoVazio(),
    cobranca: { emailCobranca: '', formaPreferida: null, diaVencimento: null, exigePedidoCompra: false, observacoes: '' },
    contatos: [],
    inadimplencia: inadimplenciaVazia(),
    convite: null, // { token, criadoEm, ativo, limite, usos: [{ alunoId, em }] } — link reutilizável para colaboradores se cadastrarem
    cadastro: null, // { token, criadoEm, preenchidoEm } — link para a própria empresa (RH/financeiro) completar o cadastro
    ...d,
  };
}

function alunoSeed(d) {
  return {
    nomeSocial: '', rg: '', nascimento: '', genero: '', profissao: '', escolaridade: null, status: 'ativo', origem: null, observacoes: '',
    email: '', celular: '', telefone: '',
    endereco: enderecoVazio(),
    empresaId: null, cargo: '',
    pagador: 'proprio',
    // Cópia derivada do vínculo com papel "financeiro" (ver `responsaveis`) — contratos, SPC e cadastro público leem daqui.
    responsavel: { nome: '', cpf: '', parentesco: '', email: '', celular: '' },
    responsaveis: [], // [{ responsavelId, parentesco, papeis: ['legal'|'financeiro'|'contato'], principal }]
    cobranca: { formaPreferida: null, diaVencimento: null },
    consentimentos: { comunicacoes: false, imagem: false, termoAceiteEm: '' },
    inadimplencia: inadimplenciaVazia(),
    necessidades: necessidadesVazias(),
    convite: null, // { token, criadoEm, preenchidoEm } — link para o próprio aluno completar o cadastro
    ...d,
  };
}
