function responsavelSeed(d) {
  return {
    nome: '', cpf: '', rg: '', nascimento: '', profissao: '', email: '', celular: '', telefone: '', observacoes: '', status: 'ativo',
    endereco: enderecoVazio(),
    ...d,
  };
}

// Semente: os responsáveis financeiros que já existiam nos alunos viram cadastros próprios (endereço = o do aluno),
// vinculados como legal + financeiro (todos são pai/mãe de menor de idade); depois alguns vínculos extras.
const RESPONSAVEIS_SEED = [];
(function semearResponsaveis() {
  const parentescoId = (txt) => ({ 'mãe': 'mae', 'pai': 'pai' }[String(txt).toLowerCase()] ?? 'outro');
  ALUNOS_SEED.forEach((a) => {
    if (a.pagador !== 'terceiro' || !a.responsavel.nome) return;
    const r = responsavelSeed({ id: `r${RESPONSAVEIS_SEED.length + 1}`, nome: a.responsavel.nome, cpf: a.responsavel.cpf, email: a.responsavel.email, celular: a.responsavel.celular, endereco: { ...a.endereco } });
    RESPONSAVEIS_SEED.push(r);
    a.responsaveis = [{ responsavelId: r.id, parentesco: parentescoId(a.responsavel.parentesco), papeis: ['legal', 'financeiro', 'contato'], principal: true }];
  });
  const extra = (alunoId, d, vinculo) => {
    const r = responsavelSeed({ id: `r${RESPONSAVEIS_SEED.length + 1}`, ...d });
    RESPONSAVEIS_SEED.push(r);
    const a = ALUNOS_SEED.find((x) => x.id === alunoId);
    a.responsaveis = [...(a.responsaveis ?? []), { responsavelId: r.id, principal: false, ...vinculo }];
  };
  // Gustavo (a1): pai como contato de emergência.
  extra('a1', { nome: 'Ronaldo Queiroz', cpf: '69212713823', profissao: 'Motorista', email: 'ronaldo.queiroz@gmail.com', celular: '47991204418', endereco: endereco('89035401', 'Rua Progresso', '1805', '', 'Tapajós', 'Indaial', 'SC') }, { parentesco: 'pai', papeis: ['contato'] });
  // Samuel (a13): mãe como responsável legal e contato (o pai paga).
  extra('a13', { nome: 'Patrícia Siqueira', cpf: '00046408614', profissao: 'Enfermeira', email: 'patricia.siqueira@hotmail.com', celular: '47988713290', endereco: endereco('89035100', 'Rua XV de Novembro', '1200', 'Ap 41', 'Centro', 'Blumenau', 'SC') }, { parentesco: 'mae', papeis: ['legal', 'contato'] });
  // Augusto (a27): avó como contato de emergência (mora perto da escola).
  extra('a27', { nome: 'Terezinha da Veiga', cpf: '52780182407', nascimento: '1954-03-02', profissao: 'Aposentada', email: '', celular: '47999011234', telefone: '4733221100', endereco: endereco('89010200', 'Rua Sete de Setembro', '450', '', 'Centro', 'Blumenau', 'SC'), observacoes: 'Não usa WhatsApp — ligar no fixo.' }, { parentesco: 'avo-f', papeis: ['contato'] });
  // Erick (a5), maior de idade desde 03/2026: mãe segue como contato de emergência.
  extra('a5', { nome: 'Denise Krüger', cpf: '94514867390', profissao: 'Professora', email: 'denise.kruger@gmail.com', celular: '47997350081', endereco: endereco('89040000', 'Rua Itajaí', '2210', '', 'Vorstadt', 'Blumenau', 'SC') }, { parentesco: 'mae', papeis: ['contato'], principal: true });
})();

